{
	struct s_list	*next;
	void			*data;
}					t_list;

void	ft_list_sort(t_list **begin_list, int (*cmp)(void *, void *))
{
	t_list	*current;
	void	*tmp;
	int		swapped;

	if (!*begin_list)
		return ;
	swapped = 1;
	while (swapped)
	{
		swapped = 0;
		current = *begin_list;
		while (current->next)
		{
			if (cmp(current->data, current->next->data) > 0)
			{
				tmp = current->data;
				current->data = current->next->data;
				current->next->data = tmp;
				swapped = 1;
			}
			current = current->next;
		}
	}
}

