{
	struct s_list	*next;
	void			*data;
}					t_list;

static t_list	*node_at(t_list *list, int idx)
{
	while (idx-- > 0)
		list = list->next;
	return (list);
}

static int	list_len(t_list *list)
{
	int	n;

	n = 0;
	while (list)
	{
		n++;
		list = list->next;
	}
	return (n);
}

void	ft_list_reverse_fun(t_list *begin_list)
{
