	int		i;
	t_list	*a;
	t_list	*b;
	void	*tmp;

	len = list_len(begin_list);
	i = 0;
	while (i < len / 2)
	{
		a = node_at(begin_list, i);
		b = node_at(begin_list, len - 1 - i);
		tmp = a->data;
		a->data = b->data;
		b->data = tmp;
		i++;
	}
}

